from pathlib import Path
from html import escape
from make_proofs import ROWS
ROOT=Path(__file__).resolve().parents[1]
rows=''.join(f'<section class="row"><label id="l-{tag}">{lang}</label><div class="sample" lang="{tag}" role="textbox" aria-labelledby="l-{tag}" contenteditable="true" spellcheck="false">{escape(text)}</div></section>' for lang,tag,text in ROWS)
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AT-KPN — Eight languages, one family</title><link rel="stylesheet" href="../web/AT-KPN.css"><style>
:root{--size:80px;--weight:700;color:#17251d;background:#faf9f5;font-family:Arial,sans-serif}*{box-sizing:border-box}body{margin:0 auto;padding:48px 5vw;max-width:1440px}header{border-bottom:1px solid #c4cbc3;padding-bottom:36px}h1{font-family:'AT-KPN';font-size:60px;font-weight:700;line-height:1.2;margin:0 0 14px}header p{font-size:17px;line-height:1.6;max-width:700px;margin:10px 0;color:#526257}.edition{font-size:12px;letter-spacing:1px;text-transform:uppercase}nav{display:flex;flex-wrap:wrap;align-items:center;gap:24px;margin-top:24px}nav label{display:flex;align-items:center;gap:10px}select{font:inherit;padding:8px 12px;background:transparent;border:1px solid #88998b;border-radius:3px}input{accent-color:#254b35}a{color:#244d35;text-underline-offset:4px}#status{font-size:13px;color:#526257}main{margin-top:10px}.row{display:grid;grid-template-columns:150px 1fr;align-items:center;min-height:170px;border-bottom:1px solid #d3d9d0;gap:24px}.row label{text-transform:uppercase;letter-spacing:.7px;font-size:13px;color:#526257}.sample{font-family:'AT-KPN';font-size:var(--size);font-weight:var(--weight);font-synthesis:none;line-height:1.6;padding:16px 0;min-width:0;overflow-wrap:anywhere}.sample[lang="ml"]{font-feature-settings:"ss01" var(--stacked,0)}.sample:focus{outline:1px solid #71917b;outline-offset:7px}footer{padding:40px 0;font-size:14px;line-height:1.8;color:#526257}.downloads{display:flex;flex-wrap:wrap;gap:20px;margin:20px 0}details{margin:24px 0}summary{cursor:pointer}details img{display:block;max-width:700px;width:100%;margin-top:20px}@media(max-width:700px){body{padding:30px 6vw}:root{--size:52px}h1{font-size:48px}.row{display:block;padding:25px 0}.row label{display:block}.sample{padding:12px 0;line-height:1.6}.row{min-height:0}nav{gap:16px}nav label{flex-wrap:wrap}}
</style><header><div class="edition">Version 0.600 · 23 November 2026</div><h1>AT-KPN</h1><p>Rounded letterforms with refined terminals, circular dots and balanced conjuncts. English, Kannada, Hindi, Marathi, Malayalam, Tamil, Telugu and Bengali.</p><nav><label>Weight <select id="weight"><option value="300">Light</option><option value="400">Regular</option><option value="700" selected>Bold</option></select></label><label>Size <input id="size" type="range" min="32" max="120" value="80"><output id="size-value">80 px</output></label><label>Malayalam form <select id="ml-form"><option value="0" selected>Inline</option><option value="1">Stacked</option></select></label><span id="status" aria-live="polite">Loading fonts…</span></nav></header><main>'''+rows+'''</main><footer><p>Click any sample to try your own text. All samples use the actual AT-KPN web fonts.</p><div class="downloads"><a href="../desktop/AT-KPN-Light.ttf" download>Light TTF</a><a href="../desktop/AT-KPN-Regular.ttf" download>Regular TTF</a><a href="../desktop/AT-KPN-Bold.ttf" download>Bold TTF</a><a href="AT-KPN-family-overview.png">View all weights</a><a href="AT-KPN-refinement-comparison.png">Compare the refinement</a><a href="../OFL.txt">Open font license</a></div><p>Adapted from Baloo 2 by Ek Type, with AT-KPN outline and proportion changes. Cocon was the visual reference. The package includes editable sources and build tools.</p><details><summary>Approved design direction</summary><p>Concept artwork used to guide the family. The working fonts retain valid Unicode shaping.</p><img src="../design/approved-concept.png" alt="The approved AT-KPN Study 02 visual concept"></details></footer><script>
document.getElementById('ml-form').addEventListener('change',event=>document.documentElement.style.setProperty('--stacked',event.target.value));
const root=document.documentElement,weight=document.getElementById('weight'),size=document.getElementById('size'),output=document.getElementById('size-value');
weight.addEventListener('change',()=>root.style.setProperty('--weight',weight.value));
if(innerWidth<700){size.value=52;output.textContent='52 px'}
size.addEventListener('input',()=>{root.style.setProperty('--size',size.value+'px');output.textContent=size.value+' px'});
Promise.all([300,400,700].map(w=>document.fonts.load(`${w} 64px "AT-KPN"`))).then(a=>{document.getElementById('status').textContent=a.every(v=>v.length)?'All three weights loaded':'Font loading incomplete'}).catch(()=>{document.getElementById('status').textContent='Font loading failed — check the web folder'});
</script></html>'''
(ROOT/'specimen/index.html').write_text(html)
